from taf.internal.core import ReusableFactory
from ..entities.managed_oam_connection import ManagedOamConnection


class ManagedOamConnectionFactory(ReusableFactory):
    _product_class = ManagedOamConnection
    _mandatory_parameters = {"oam_connection_cls", "oam_connection_params"}
    _existing_product_objects = {}

    def __init__(self, oam_connection_cls, **kwargs):
        super().__init__(**kwargs)
        self._oam_connection_cls = oam_connection_cls

    @property
    def oam_connection_cls(self):
        return self._oam_connection_cls

    def create(self, configuration, existing_arguments=None):
        return super().create(
            configuration=configuration | {"oam_connection_cls": self._oam_connection_cls},
            existing_arguments=existing_arguments)

    @staticmethod
    def _create_unique_key(resulting_arguments):
        params = resulting_arguments.get("oam_connection_params", {})
        reuse = params.get("reuse", True)
        unique_key = tuple(sorted(
            (k, d[k])
            for k in ("user", "host", "port", "release", "remote_host")
            if k in (d := params)
        ))
        return unique_key, reuse


def CreatingOamConnection(oam_connection_cls, attr_name="managed_oam_connection", oam_config_name="webservice"):
    class CreatingOamConnectionTemplate(object):
        def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
            super(CreatingOamConnectionTemplate, self)._build_arguments(
                configuration=configuration,
                existing_arguments=existing_arguments,
                resulting_arguments=resulting_arguments,
            )
            resulting_arguments[attr_name] = ManagedOamConnectionFactory(oam_connection_cls).create(
                configuration={"oam_connection_params": configuration[oam_config_name]},
                existing_arguments={}
            )

    return CreatingOamConnectionTemplate
